  "confidence": 0.93,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["R3", "R10", "R16", "R18"],
      "pins": ["J2.19", "J2.21", "J2.20", "J2.22"],
      "nets": ["/NET0011", "/NET0015", "/NET0028", "/NET0038", "/NET0042", "/NET0036"],
      "observed": "The 0 Ω links R16 and R18 connect J2 pins 19 and 21 to the same net. The 0 Ω links R10 and R3 likewise connect J2 pins 20 and 22 to the same net. Thus both alternative GPIO mappings are joined in the design.",
      "expected": "The specification describes variant-dependent jumper selection between these bus pins, not simultaneous connection of both alternatives. The two GPIO pins in each pair should remain separate; only the appropriate mapping should be fitted for the M5Stack variant.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0011\") ... (node (ref \"J2\") (pin \"19\")) ... (node (ref \"R16\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0015\") ... (node (ref \"J2\") (pin \"21\")) ... (node (ref \"R18\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0028\") ... (node (ref \"J2\") (pin \"20\")) ... (node (ref \"R10\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0038\") ... (node (ref \"J2\") (pin \"22\")) ... (node (ref \"R3\") (pin \"2\")))"
        },
        {
          "source": "spec",
          "quote": "R9–R12 | 0 Ω (jumpers) | Select which M5Stack bus pin (pin 19/21 for ch.1, pin 20/22 for ch.2) supplies PWM1/PWM2"
        }
      ],
      "impact": "The paired M5Stack GPIO pins are electrically shorted through the zero-ohm links. If both pins are driven independently, this can cause output contention and prevent the intended variant-specific PWM mapping from working correctly.",
      "confidence": 0.93
    }
  ],
  "summary": "The netlist shows zero-ohm links joining both GPIO alternatives in each mapping pair (pins 19/21 and 20/22). This conflicts with the specification’s variant-dependent jumper selection and can short independently driven GPIOs."
}

